<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Employee } from '../domain/types'
import { commit, db, month, navigate, openImport, saveEmployee, selectedEmployee } from '../store'
import { activeOn, orderedEmployees } from '../domain/model'
import { today, uid } from '../domain/dates'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const search = ref(''), showInactive = ref(false), editor = ref<Employee>()
const all = computed(() => orderedEmployees(db.value)), rows = computed(() => all.value.filter(e => `${e.name}${e.code}`.includes(search.value) && (showInactive.value || !e.to || e.to > today())))
function add() {
  let n = db.value.employees.length + 1
  while (db.value.employees.some(e => e.code === `E${String(n).padStart(3,'0')}`)) n++
  editor.value = { id: uid(), code: `E${String(n).padStart(3,'0')}`, name: '', from: `${month.value}-01`, to: '', order: db.value.employees.length, note: '' }
}
async function save() { if (editor.value && await saveEmployee({ ...editor.value, name: editor.value.name.trim(), code: editor.value.code.trim() })) editor.value = undefined }
async function move(employee: Employee, offset: number) {
  const position = all.value.findIndex(e => e.id === employee.id), other = all.value[position + offset]; if (!other) return
  await commit('已调整名单顺序', employee.name, d => { const ids = all.value.map(e => e.id); [ids[position], ids[position+offset]] = [ids[position+offset]!, ids[position]!]; ids.forEach((id,i) => { d.employees.find(e => e.id === id)!.order = i }) })
}
function view(employee: Employee) { selectedEmployee.value = employee.id; navigate('schedule') }
</script>
<template><section class="page-heading"><div><h1>员工管理</h1><p>维护名单与优先顺序。搭档随休假动态配对，无需固定分组。</p></div><div class="actions"><button class="button secondary" @click="openImport('employees')">导入员工名单</button><button class="button primary" @click="add"><Icon name="plus" :size="18" />新增员工</button></div></section><section class="panel"><div class="schedule-toolbar"><div class="search-field"><Icon name="search" :size="17" /><input v-model="search" placeholder="搜索姓名或员工编号" aria-label="搜索员工资料" /></div><label class="checkbox-line"><input v-model="showInactive" type="checkbox" />显示已停用员工</label><span class="toolbar-end muted">共{{ db.employees.length }}人 · 当前显示{{ rows.length }}人</span></div><div class="callout flat"><Icon name="info" :size="18" /><p>名单靠前的员工优先满足早晚段与房间目标；任何优先级都不能突破每班两人的硬约束。</p></div><div class="table-scroll"><table class="data-table"><thead><tr><th>优先顺序</th><th>员工</th><th>编号</th><th>生效日期</th><th>停用日期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="employee in rows" :key="employee.id"><td><div class="order-control"><span>{{ all.findIndex(e => e.id === employee.id) + 1 }}</span><button class="icon-button" :disabled="all[0]?.id === employee.id" :aria-label="`${employee.name}上移`" @click="move(employee,-1)">↑</button><button class="icon-button" :disabled="all.at(-1)?.id === employee.id" :aria-label="`${employee.name}下移`" @click="move(employee,1)">↓</button></div></td><td><div class="employee-name"><span class="avatar tiny">{{ employee.name.slice(-1) }}</span><strong>{{ employee.name }}</strong></div></td><td class="muted">{{ employee.code }}</td><td>{{ employee.from || '未设置' }}</td><td>{{ employee.to || '—' }}</td><td><span class="pill" :class="activeOn(employee,today()) ? 'success' : ''">{{ employee.from > today() ? '待生效' : employee.to && employee.to <= today() ? '已停用' : '在职' }}</span></td><td><div class="actions"><button class="text-button" @click="editor = { ...employee }">编辑</button><button class="text-button muted" @click="view(employee)">查看排班</button></div></td></tr><tr v-if="!rows.length"><td colspan="7" class="empty-table">暂无符合条件的员工。可新增员工，或从Excel导入名单与历史。</td></tr></tbody></table></div></section><div class="info-footnote"><Icon name="shield" :size="17" />停用保留历史记录；从停用日期当天起，不再参与新自动排班。</div><Modal :open="!!editor" :title="db.employees.some(e => e.id === editor?.id) ? '编辑员工资料' : '新增员工'" @close="editor = undefined"><form v-if="editor" id="employee-form" @submit.prevent="save"><div class="form-grid"><label class="field">员工编号<input v-model="editor.code" required maxlength="40" /></label><label class="field">姓名<input v-model="editor.name" required maxlength="40" /></label><label class="field">生效日期<input v-model="editor.from" type="date" /></label><label class="field">停用日期（当天起不排）<input v-model="editor.to" type="date" :min="editor.from" /></label></div><label class="field">备注<textarea v-model="editor.note" rows="3" placeholder="补充员工说明" /></label><p class="fineprint">同名员工使用不同编号识别。新员工没有历史时，不会被假定有上月光子或房间经历。</p></form><template #footer><button class="button secondary" @click="editor = undefined">取消</button><button class="button primary" form="employee-form" type="submit">保存员工</button></template></Modal></template>
